/* dock protocol topic template: thing/product/<sn>/<channel>; no cap segment, no V1/V2 distinction. */
static void build_dock_topic(char *out, size_t cap, const char *sn, const char *channel)
{
    snprintf(out, cap, "thing/product/%s/%s", sn ? sn : "", channel ? channel : "");
}

char *ChargingDock_BuildTopic(const char *sn, const char *channel)
{
    char buf[256];
    build_dock_topic(buf, sizeof(buf), sn, channel);
    return ThingModelMem_Strdup(buf);
}

/* ============================================================ */
/* pending table (paired by tid)                                 */
/* ============================================================ */

typedef enum { PEND_SYNC, PEND_ASYNC, PEND_ASYNC_TYPED } EPendKind;

/* PEND_ASYNC_TYPED — lets the dispatcher handle all typed replies in one piece of code */
typedef T_ThingModelReturnCode (*_TypedDecoder)(const char *json, void *out_reply);
typedef void                   (*_TypedAsyncCb)(void *user, T_ThingModelReturnCode rc, const void *typed_reply);

typedef struct PendingEntry {
    struct PendingEntry *next;
    char       tid[64];               /* paired with the tid produced by <Pkg>Dock_EncodeRequest */
    char       reply_topic[256];      /* full requests_reply topic */
    char       expect_method[96];     /* only a hit if the method matches (guards against mix-ups) */
    EPendKind  kind;
    bool       fired;

    /* sync path */
    void      *event;
    char      *sync_buf;
    size_t     sync_buf_cap;
    size_t     sync_buf_len;

    /* async CommonReply */
    T_ThingModelAsyncReplyCb cb;
    void *cb_user;

    /* async typed reply */
    _TypedAsyncCb typed_cb;
    _TypedDecoder typed_decoder;
    size_t        typed_reply_size;
} PendingEntry_t;

struct ChargingDock_Client {
    ThingModelClientSession_t *session;
    char                       topic_requests[256];
    char                       topic_requests_reply[256];
    int32_t                    listener_handle;
    void                      *lock;
    PendingEntry_t            *pending;
};

/* ============================================================ */
/* on_message dispatch (find pending by tid)                     */
/* ============================================================ */

static void on_session_message(void *user, const char *topic,
                               const char *payload, size_t len)
{
    ChargingDock_Client_t *c = user;
    const T_ThingModelOsal *o = ThingModelClientSession_GetOsal(c->session);

    if (strcmp(topic, c->topic_requests_reply) != 0) return;

    ThingModelJsonObj_t *root = ThingModelJson_ParseN(payload, len);
    if (!root) return;
    T_ChargingDockEnvelope env = {0};
    if (!ChargingDock_ParseEnvelope(root, &env)) {
        ThingModelJson_Free(root);
        return;
    }

    /* Find pending inside the lock, deliver sync inside the lock, call async back outside the lock (same pattern as Things-Model) */
    PendingEntry_t *hit = NULL;
    o->mutex_lock(c->lock);
    PendingEntry_t **pp = &c->pending;
    while (*pp) {
        PendingEntry_t *e = *pp;
        if (env.tid && strcmp(e->tid, env.tid) == 0
            && (!e->expect_method[0] || (env.method && strcmp(e->expect_method, env.method) == 0))) {
            *pp = e->next;
            hit = e;
            break;
        }
        pp = &e->next;
    }
    if (hit && hit->kind == PEND_SYNC) {
        if (hit->sync_buf && len < hit->sync_buf_cap) {
            memcpy(hit->sync_buf, payload, len);
            hit->sync_buf[len] = 0;
            hit->sync_buf_len  = len;
        }
        hit->fired = true;
        o->event_signal(hit->event);
        o->mutex_unlock(c->lock);
        ThingModelJson_Free(root);
        return;
    }
    o->mutex_unlock(c->lock);

    if (hit) {
        if (hit->kind == PEND_ASYNC_TYPED) {
            if (hit->typed_cb) {
                void *r = ThingModelMem_Calloc(1, hit->typed_reply_size);
                if (r) {
                    T_ThingModelReturnCode drc = THING_MODEL_RC_OK;
                    if (hit->typed_decoder) drc = hit->typed_decoder(payload, r);
                    hit->typed_cb(hit->cb_user, drc, r);
                    ThingModelMem_Free(r);
                } else {
                    hit->typed_cb(hit->cb_user, THING_MODEL_RC_OUT_OF_MEMORY, NULL);
                }
            }
        } else if (hit->cb) {
            /* ESDK CommonReply: data.result + data.error_reason */
            T_ThingModelCommonReply r = {0};
            if (env.data) {
                r.result = (int32_t)ThingModelJson_LookupInt(env.data, "result", 0);
                snprintf(r.result_message, sizeof(r.result_message), "%s",
                         ThingModelJson_LookupString(env.data, "error_reason", ""));
            }
            hit->cb(hit->cb_user, THING_MODEL_RC_OK, &r);
        }
        ThingModelMem_Free(hit);
    }
    ThingModelJson_Free(root);
}

/* ============================================================ */
/* sync / async / typed_async helpers                            */
/* ============================================================ */

/* Extract the tid from the wire payload (used to register the pending entry for reply pairing). */
static void _extract_tid(const char *payload_json, char *out_tid, size_t cap)
{
    out_tid[0] = 0;
    ThingModelJsonObj_t *r = ThingModelJson_Parse(payload_json);
    if (!r) return;
    const char *tid = ThingModelJson_LookupString(r, "tid", NULL);
    if (tid) snprintf(out_tid, cap, "%s", tid);
    ThingModelJson_Free(r);
}

static T_ThingModelReturnCode call_sync(ChargingDock_Client_t *c,
                                       const char *method,
                                       const char *payload_json,
                                       char *out_buf, size_t out_cap, uint32_t timeout_ms)
{
    const T_ThingModelOsal *o = ThingModelClientSession_GetOsal(c->session);

    PendingEntry_t e = {0};
    _extract_tid(payload_json, e.tid, sizeof(e.tid));
    if (!e.tid[0]) return THING_MODEL_RC_INVALID_ARG;  /* tid is empty when the business code forgot to register an IdProvider */

    e.kind         = PEND_SYNC;
    e.event        = o->event_create();
    e.sync_buf     = out_buf;
    e.sync_buf_cap = out_cap;
    snprintf(e.reply_topic, sizeof(e.reply_topic), "%s", c->topic_requests_reply);
    if (method) snprintf(e.expect_method, sizeof(e.expect_method), "%s", method);

    o->mutex_lock(c->lock);
    e.next = c->pending;
    c->pending = &e;
    o->mutex_unlock(c->lock);

    T_ThingModelReturnCode rc = ThingModelClientSession_Publish(c->session, c->topic_requests, payload_json, 1);
    if (THING_MODEL_IS_OK(rc)) {
        int wr = o->event_wait(e.event, timeout_ms);
        rc = (wr == 0 && e.fired) ? THING_MODEL_RC_OK : THING_MODEL_RC_TIMEOUT;
    }

    o->mutex_lock(c->lock);
    bool still_in_list = false;
    PendingEntry_t **pp = &c->pending;
    while (*pp) {
        if (*pp == &e) { *pp = e.next; still_in_list = true; break; }
        pp = &(*pp)->next;
    }
    if (!still_in_list && e.fired) rc = THING_MODEL_RC_OK;
    o->mutex_unlock(c->lock);
    o->event_destroy(e.event);
    return rc;
}

static T_ThingModelReturnCode call_async(ChargingDock_Client_t *c,
                                        const char *method,
                                        const char *payload_json,
                                        T_ThingModelAsyncReplyCb cb, void *user)
{
    const T_ThingModelOsal *o = ThingModelClientSession_GetOsal(c->session);

    PendingEntry_t *e = ThingModelMem_Calloc(1, sizeof(*e));
    if (!e) return THING_MODEL_RC_OUT_OF_MEMORY;
    _extract_tid(payload_json, e->tid, sizeof(e->tid));
    if (!e->tid[0]) { ThingModelMem_Free(e); return THING_MODEL_RC_INVALID_ARG; }

    e->kind    = PEND_ASYNC;
    e->cb      = cb;
    e->cb_user = user;
    snprintf(e->reply_topic, sizeof(e->reply_topic), "%s", c->topic_requests_reply);
    if (method) snprintf(e->expect_method, sizeof(e->expect_method), "%s", method);

    o->mutex_lock(c->lock);
    e->next    = c->pending;
    c->pending = e;
    o->mutex_unlock(c->lock);

    T_ThingModelReturnCode rc = ThingModelClientSession_Publish(c->session, c->topic_requests, payload_json, 1);
    if (!THING_MODEL_IS_OK(rc)) {
        o->mutex_lock(c->lock);
        PendingEntry_t **pp = &c->pending;
        while (*pp) { if (*pp == e) { *pp = e->next; break; } pp = &(*pp)->next; }
        o->mutex_unlock(c->lock);
        ThingModelMem_Free(e);
    }
    return rc;
}

static T_ThingModelReturnCode call_async_typed(ChargingDock_Client_t *c,
                                              const char *method,
                                              const char *payload_json,
                                              _TypedAsyncCb typed_cb, void *user,
                                              _TypedDecoder decoder, size_t reply_size)
{
    const T_ThingModelOsal *o = ThingModelClientSession_GetOsal(c->session);

    PendingEntry_t *e = ThingModelMem_Calloc(1, sizeof(*e));
    if (!e) return THING_MODEL_RC_OUT_OF_MEMORY;
    _extract_tid(payload_json, e->tid, sizeof(e->tid));
    if (!e->tid[0]) { ThingModelMem_Free(e); return THING_MODEL_RC_INVALID_ARG; }

    e->kind             = PEND_ASYNC_TYPED;
    e->typed_cb         = typed_cb;
    e->cb_user          = user;
    e->typed_decoder    = decoder;
    e->typed_reply_size = reply_size;
    snprintf(e->reply_topic, sizeof(e->reply_topic), "%s", c->topic_requests_reply);
    if (method) snprintf(e->expect_method, sizeof(e->expect_method), "%s", method);

    o->mutex_lock(c->lock);
    e->next    = c->pending;
    c->pending = e;
    o->mutex_unlock(c->lock);

    T_ThingModelReturnCode rc = ThingModelClientSession_Publish(c->session, c->topic_requests, payload_json, 1);
    if (!THING_MODEL_IS_OK(rc)) {
        o->mutex_lock(c->lock);
        PendingEntry_t **pp = &c->pending;
        while (*pp) { if (*pp == e) { *pp = e->next; break; } pp = &(*pp)->next; }
        o->mutex_unlock(c->lock);
        ThingModelMem_Free(e);
    }
    return rc;
}

/* ============================================================ */
/* Create / Destroy                                              */
/* ============================================================ */

ChargingDock_Client_t *ChargingDock_CreateClient(ThingModelClientSession_t *session)
{
    if (!session) return NULL;
    const T_ThingModelOsal *o = ThingModelClientSession_GetOsal(session);
    ChargingDock_Client_t *c = ThingModelMem_Calloc(1, sizeof(*c));
    if (!c) return NULL;
    c->session = session;
    c->lock    = o->mutex_create();
    const char *sn = ThingModelClientSession_GetSn(session);
    build_dock_topic(c->topic_requests,       sizeof(c->topic_requests),       sn, CHARGING_DOCK_CHANNEL_REQUESTS);
    build_dock_topic(c->topic_requests_reply, sizeof(c->topic_requests_reply), sn, CHARGING_DOCK_CHANNEL_REQUESTS_REPLY);

    c->listener_handle = ThingModelClientSession_AddListener(session, on_session_message, c);
    ThingModelClientSession_Subscribe(session, c->topic_requests_reply, 1);
    return c;
}

void ChargingDock_DestroyClient(ChargingDock_Client_t *c)
{
    if (!c) return;
    const T_ThingModelOsal *o = ThingModelClientSession_GetOsal(c->session);
    ThingModelClientSession_RemoveListener(c->session, c->listener_handle);
    ThingModelClientSession_Unsubscribe(c->session, c->topic_requests_reply);
    PendingEntry_t *p = c->pending;
    while (p) { PendingEntry_t *n = p->next; if (p->kind != PEND_SYNC) ThingModelMem_Free(p); p = n; }
    if (c->lock) o->mutex_destroy(c->lock);
    ThingModelMem_Free(c);
}

