char *ChargingDock_BuildDroneOpenPayload(const T_DroneOpenRequest *req)
{
    char *data = req ? ChargingJson_EncodeDroneOpenRequest(req) : NULL;
    char *payload = ChargingDock_EncodeRequest(CHARGING_METHOD_DRONE_OPEN, "1.0.0", data);
    if (data) ThingModelMem_Free(data);
    return payload;
}

/* typed reply: ESDK stuffs the typed fields in data.output; parse the envelope first, then decode data.output */
static T_ThingModelReturnCode _decode_drone_open_reply(const char *json, void *out_reply)
{
    if (!json || !out_reply) return THING_MODEL_RC_INVALID_ARG;
    memset(out_reply, 0, sizeof(T_ActionStatus));
    ThingModelJsonObj_t *root = ThingModelJson_Parse(json);
    if (!root) return THING_MODEL_RC_DECODE_ERROR;
    ThingModelJsonObj_t *data = ThingModelJson_GetItem(root, "data");
    int32_t _result = data ? (int32_t)ThingModelJson_LookupInt(data, "result", 0) : 0;
    ThingModelJsonObj_t *output = data ? ThingModelJson_GetItem(data, "output") : NULL;
    if (output) ChargingJson_DecodeActionStatus_FromObj(output, (T_ActionStatus *)out_reply);
    ThingModelJson_Free(root);
    /* ESDK data.result != 0 → business-side error: the reply arrived but was not successful; map to RC_UNKNOWN so the caller notices
       (a payload-only reply struct has no result slot, so the return code carries it; the specific DJI code does not go into the fixed enum). */
    return _result == 0 ? THING_MODEL_RC_OK : THING_MODEL_RC_UNKNOWN;
}

T_ThingModelReturnCode ChargingDock_DroneOpen(ChargingDock_Client_t *c, const T_DroneOpenRequest *req, T_ActionStatus *resp, uint32_t timeout_ms)
{
    char *payload = ChargingDock_BuildDroneOpenPayload(req);
    if (!payload) return THING_MODEL_RC_OUT_OF_MEMORY;
    char reply[4096];
    T_ThingModelReturnCode rc = call_sync(c, CHARGING_METHOD_DRONE_OPEN, payload, reply, sizeof(reply), timeout_ms);
    if (THING_MODEL_IS_OK(rc) && resp) rc = _decode_drone_open_reply(reply, resp);
    ThingModelMem_Free(payload);
    return rc;
}

T_ThingModelReturnCode ChargingDock_DroneOpenAsync(ChargingDock_Client_t *c, const T_DroneOpenRequest *req, ChargingDock_DroneOpen_AsyncCb cb, void *user)
{
    char *payload = ChargingDock_BuildDroneOpenPayload(req);
    if (!payload) return THING_MODEL_RC_OUT_OF_MEMORY;
    T_ThingModelReturnCode rc = call_async_typed(c, CHARGING_METHOD_DRONE_OPEN, payload,
                                                 (_TypedAsyncCb)cb, user,
                                                 _decode_drone_open_reply, sizeof(T_ActionStatus));
    ThingModelMem_Free(payload);
    return rc;
}

